    chase(target, dt, multiplier = 1) { const dx = target.x - this.x; const dy = target.y - this.y; const d = Math.hypot(dx, dy) || 1; this.x += dx / d * this.speed * multiplier * dt; this.y += dy / d * this.speed * multiplier * dt; }
