        context.fillRect(x - 8, y - 8, 5, 14);
        context.fillRect(x + 3, y - 8, 5, 14);
        context.fillRect(x - 3, y + 3, 6, 5);
        context.fillStyle = "#f5d9dd";
        context.fillRect(x - 6, y - 7, 2, 7);
        context.fillRect(x + 4, y - 7, 2, 7);
        return;
